<?php
declare(strict_types=1);
function catalogue_categories_page():void{
 admin_page('Menu categories',function(){
 ?><p class="muted">Create categories for your meals. Enable “36° Store” for treats, drinks or other products you also want in the Store. All categories remain available in the food menu.</p><form class="form" method="post" action="/admin/category/save"><?=token()?><h2>Add a category</h2><label for="category-name">Category name</label><input id="category-name" name="name" maxlength="120" required placeholder="e.g. Soups & Swallows"><label class="catalogue-check"><input type="checkbox" name="in_store"> Also show in 36° Store</label><button class="btn gold">Create category</button></form><div class="category-editor-grid"><?php foreach(all('SELECT c.*,'.catalogue_store_condition().' AS in_store FROM categories c ORDER BY c.name') as $category):?><form class="form" method="post" action="/admin/category/save"><?=token()?><input type="hidden" name="id" value="<?=(int)$category['id']?>"><label for="category-<?=(int)$category['id']?>">Category name</label><input id="category-<?=(int)$category['id']?>" name="name" value="<?=esc($category['name'])?>" maxlength="120" required><label class="catalogue-check"><input name="in_store" type="checkbox" <?=$category['in_store']?'checked':''?>> Also show in 36° Store</label><button class="btn">Save category</button></form><?php endforeach;?></div><?php
 });
}
function catalogue_product_editor():void{
 $id=(int)($_GET['id']??0);$product=$id?one('SELECT * FROM products WHERE id=?',[$id]):null;if($id&&!$product)abort(404,'Meal not found');
 $photos=$id?all('SELECT * FROM product_gallery WHERE product_id=? ORDER BY sort_order,id',[$id]):[];
 admin_page($product?'Edit Meal':'Add Meal',function()use($product,$photos){
 ?><form class="form catalogue-editor" method="post" enctype="multipart/form-data" action="/admin/product/save"><?=token()?><input type="hidden" name="id" value="<?=$product['id']??0?>"><input type="hidden" name="gallery_present" value="1"><?php field('Meal name','name','text',true,$product['name']??'');?><label for="category_id">Category</label><select id="category_id" name="category_id"><option value="">Uncategorized</option><?php foreach(all('SELECT * FROM categories ORDER BY name') as $category):?><option value="<?=(int)$category['id']?>" <?=(int)($product['category_id']??0)===(int)$category['id']?'selected':''?>><?=esc($category['name'])?></option><?php endforeach;?></select>
 <details class="catalogue-disclosure"><summary>＋ Create a new category</summary><p class="small muted">Enter a new name to create it and assign this meal when you save. Leave blank to use the category selected above.</p><label for="new_category">New category name</label><input id="new_category" name="new_category" maxlength="120" placeholder="e.g. Soups & Swallows"><label class="catalogue-check"><input type="checkbox" name="new_category_store"> Also show in 36° Store</label><a href="/admin/categories" target="_blank" rel="noopener">Manage all categories →</a></details>
 <label for="description">Description</label><textarea id="description" name="description" maxlength="4000" rows="3"><?=esc($product['description']??'')?></textarea>
 <details class="catalogue-disclosure" open><summary>Cover photo</summary><p class="small muted">Shown on menu cards and first in the gallery.</p><?php if(!empty($product['image'])):?><img class="catalogue-cover-preview" src="<?=esc($product['image'])?>" alt="Current cover"><?php endif;?><?php field('Cover image URL or media-library path','image','text',false,$product['image']??'');?><label for="product_image">Or upload a new cover photo</label><input id="product_image" type="file" name="product_image" accept="image/jpeg,image/png,image/webp"><p class="small muted">JPG, PNG or WebP · up to 6 MB per image. An upload replaces the cover URL.</p></details>
 <details class="catalogue-disclosure" <?=count($photos)?'open':''?>><summary>Additional product photos (<?=count($photos)?> / 7)</summary><p class="small muted">Show different angles, portions or packaging. Keep the cover above and add up to seven extra views. Lower order numbers appear first. Removing a photo here leaves the original media file available elsewhere.</p>
 <?php for($i=0;$i<7;$i++):$photo=$photos[$i]??null;?><details class="gallery-editor-row" <?=$photo?'open':''?>><summary><?=$photo?'Photo '.($i+1):'Add image link '.($i+1)?></summary><?php if($photo):?><img src="<?=esc($photo['image'])?>" alt="Gallery photo <?=$i+1?>" loading="lazy"><?php endif;?><label for="gallery-url-<?=$i?>">Image URL or media-library path</label><input id="gallery-url-<?=$i?>" name="gallery_url[]" value="<?=esc($photo['image']??'')?>" maxlength="1000"><label for="gallery-alt-<?=$i?>">Image description</label><input id="gallery-alt-<?=$i?>" name="gallery_alt[]" value="<?=esc($photo['alt_text']??'')?>" maxlength="180" placeholder="e.g. Side view showing the portion"><label for="gallery-order-<?=$i?>">Display order</label><input id="gallery-order-<?=$i?>" name="gallery_order[]" type="number" min="0" max="999" value="<?=$i?>"><?php if($photo):?><label class="catalogue-check"><input type="checkbox" name="gallery_remove[]" value="<?=$i?>"> Remove this view when saving</label><?php endif;?></details><?php endfor;?>
 <label for="gallery_images">Or upload additional photos together</label><input id="gallery_images" name="gallery_images[]" type="file" multiple accept="image/jpeg,image/png,image/webp"><p class="small muted">Select several photos at once. Existing links plus new uploads must total no more than seven additional images.</p></details>
 <label for="price">Price (NGN)</label><input id="price" name="price" type="number" min="0" max="10000000" step="0.01" value="<?=esc($product['price']??'0')?>" required><label class="catalogue-check"><input type="checkbox" name="available" <?=!isset($product)||$product['available']?'checked':''?>> Available to order</label><label class="catalogue-check"><input type="checkbox" name="featured" <?=($product['featured']??0)?'checked':''?>> Featured on homepage</label><button class="btn gold">Save meal & photos</button></form><?php
 });
}
